arguments.file_text:
@page "/chat"
@using sv_4dcf9d1293af41dcb5d8fbfb4da0c843.Services
@using sv_4dcf9d1293af41dcb5d8fbfb4da0c843.Components.Chat
@rendermode InteractiveServer
@inject IChatService ChatService
@implements IDisposable

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_activeChannelId"
                        OnChannelSelected="SelectChannelAsync" />
    </div>

    <div class="chat-main @(_threadOpen ? "with-thread" : "")">
        @if (_activeChannel is not null)
        {
            <MessageArea Channel="_activeChannel"
                         Messages="_messages"
                         ThreadReplyCounts="_threadReplyCounts"
                         HasMoreMessages="_hasMoreMessages"
                         IsLoadingMore="_isLoadingMore"
                         OnLoadMore="LoadMoreMessagesAsync"
                         OnSendMessage="SendMessageAsync"
                         OnOpenThread="OpenThreadAsync"
                         OnReact="HandleReactAsync" />
        }
    </div>

    @if (_threadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReplyAsync" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private int _activeChannelId;
    private Channel? _activeChannel;
    private int _messagesLoaded;
    private bool _hasMoreMessages = true;
    private bool _isLoadingMore;

    // Thread state
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadMessages = [];
    private Dictionary<int, int> _threadReplyCounts = [];

    private CancellationTokenSource _cts = new();

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();

        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0].Id);
        }
    }

    private async Task SelectChannelAsync(int channelId)
    {
        if (_activeChannelId == channelId) return;

        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = [];
        _messagesLoaded = 0;
        _hasMoreMessages = true;
        _threadOpen = false;
        _threadReplyCounts = [];

        await LoadMessagesAsync();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the unread count in the local channel list
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadMessagesAsync()
    {
        var batch = await ChatService.GetMessagesAsync(_activeChannelId, _messagesLoaded, PageSize);
        _messages.AddRange(batch);
        _messagesLoaded += batch.Count;
        _hasMoreMessages = batch.Count == PageSize;
        await UpdateThreadReplyCountsAsync(batch);
    }

    private async Task LoadMoreMessagesAsync()
    {
        if (_isLoadingMore) return;
        _isLoadingMore = true;

        try
        {
            var batch = await ChatService.GetMessagesAsync(_activeChannelId, _messagesLoaded, PageSize);

            // Prepend older messages
            _messages.InsertRange(0, batch);
            _messagesLoaded += batch.Count;
            _hasMoreMessages = batch.Count == PageSize;
            await UpdateThreadReplyCountsAsync(batch);
        }
        finally
        {
            _isLoadingMore = false;
        }
    }

    private async Task UpdateThreadReplyCountsAsync(List<Message> messages)
    {
        // For each message that has no ReplyToId (potential thread starter),
        // check if it has replies by looking at other messages referencing it
        foreach (var msg in messages.Where(m => m.ReplyToId is null))
        {
            try
            {
                var thread = await ChatService.GetThreadAsync(msg.Id);
                if (thread.Count > 0)
                {
                    _threadReplyCounts[msg.Id] = thread.Count;
                }
            }
            catch
            {
                // Thread may not exist; that's fine
            }
        }
    }

    private async Task SendMessageAsync(string content)
    {
        var message = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(message);
        _messagesLoaded++;
    }

    private async Task OpenThreadAsync(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadMessages = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = [];
    }

    private async Task SendThreadReplyAsync(string content)
    {
        if (_threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(
            _activeChannelId, content, _threadRootMessage.Id);

        _threadMessages.Add(reply);

        // Update reply count in the main view
        _threadReplyCounts[_threadRootMessage.Id] = _threadMessages.Count;
    }

    private async Task HandleReactAsync((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the local message
        var idx = _messages.FindIndex(m => m.Id == args.MessageId);
        if (idx >= 0)
        {
            var msg = _messages[idx];
            var reactions = msg.Reactions.ToList();
            var existing = reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing is not null)
            {
                reactions.Remove(existing);
                reactions.Add(existing with { Users = [..existing.Users, "You"] });
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
            _messages[idx] = msg with { Reactions = reactions };
        }
    }

    public void Dispose()
    {
        _cts.Cancel();
        _cts.Dispose();
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    background-color: #1e1e1e;
    color: #e0e0e0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

